((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
globalThis.KENGURU_GRADES_7_8 = [{"id":"2022-9-10","year":2022,"grades":[9,10,11],"label":"9–11 классы","tasksUrl":"assets/kenguru/kenguru_2022_class_9-10.pdf","answersUrl":"assets/kenguru/kenguru_2022_answers.pdf","solutionUrl":"assets/kenguru/kenguru_2022_solution-reviewed.pdf","answerLetters":"АБВГД","cards":[{"number":1,"title":"Число из спичек","question":"Лена составляет из спичек число 2022. Изначально в коробке было 30 спичек, и Лена уже использовала какое-то количество, чтобы сложить первые две цифры так, как показано на рисунке. Сколько спичек останется в коробке, когда Лена сложит всё число целиком?","options":[{"text":"20"},{"text":"19"},{"text":"10"},{"text":"9"},{"text":"5"}],"condition":{"src":"assets/grades-9-10/2022/task-01.svg","width":146,"height":104,"alt":"Из спичек выложено 20. Цифра 2 сделана из пяти спичек, цифра 0 — из шести"},"answer":3,"points":3,"review":[{"title":"Спички на цифры","text":"Для цифры 2 нужно пять спичек, для 0 — шесть. В записи 2022 три цифры 2 и одна цифра 0."},{"title":"Остаток в коробке","text":"Уйдёт 3 × 5 + 6 = 21 спичка. Останется 30 − 21 = 9."}],"keyNote":null},{"number":2,"title":"Одинаковые периметры","question":"Периметры равностороннего треугольника со стороной 12 и квадрата со стороной x совпадают. Чему равно значение x?","options":[{"text":"9"},{"text":"12"},{"text":"16"},{"text":"24"},{"text":"36"}],"condition":null,"answer":0,"points":3,"review":[{"title":"Периметр треугольника","text":"У треугольника три стороны по 12. Его периметр равен 36."},{"title":"Сторона квадрата","text":"Четыре равные стороны квадрата также дают 36. Поэтому x = 36/4 = 9."}],"keyNote":null},{"number":3,"title":"Кусок таблицы умножения","question":"На рисунке приведён кусок таблицы умножения. На пересечении столбца и строки указано произведение соответствующих чисел. Три значения произведений из четырёх были стёрты. Известно, что числа x и y натуральные, и при этом x > y. Чему равно значение x?","options":[{"text":"6"},{"text":"7"},{"text":"8"},{"text":"10"},{"text":"11"}],"condition":{"src":"assets/grades-9-10/2022/task-03.svg","width":262,"height":231,"alt":"Столбцы подписаны x и x + 1, строки — y и y + 1. В правой нижней клетке стоит 77"},"answer":3,"points":3,"review":[{"title":"Что означает 77","text":"Нижняя правая клетка даёт (x + 1)(y + 1) = 77. Оба множителя больше 1."},{"title":"Разложение числа","text":"77 = 11 × 7. Поскольку x больше y, имеем x + 1 = 11 и y + 1 = 7. Значит, x = 10."}],"keyNote":null},{"number":4,"title":"Число и его квадрат","question":"Я меньше своей половины и больше своего удвоенного значения. Сумма меня и моего квадрата равна нулю. Кто я?","options":[{"text":"−2"},{"text":"−1"},{"text":"0"},{"text":"1"},{"text":"2"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Два кандидата","text":"Если число равно t, то t + t² = t(t + 1) = 0. Возможны 0 и −1."},{"title":"Проверяем неравенства","text":"Нуль равен своей половине и своему удвоенному значению. Для −1 верно −2 < −1 < −1/2, поэтому подходит −1."}],"keyNote":null},{"number":5,"title":"Ромб в прямоугольнике","question":"Середины больших сторон прямоугольника соединены со всеми его вершинами. Какая часть площади прямоугольника на рисунке закрашена?","options":[{"text":"1/5"},{"text":"1/4"},{"text":"2/7"},{"text":"1/3"},{"text":"2/5"}],"condition":{"src":"assets/grades-9-10/2022/task-05.svg","width":201,"height":138,"alt":"Две середины длинных сторон прямоугольника соединены с его вершинами. Закрашен ромб в центре"},"answer":1,"points":3,"review":[{"title":"Половины прямоугольника","text":"Разделим прямоугольник вертикалью через середины его длинных сторон. Обе половины разбиты диагоналями на четыре треугольника одинаковой площади."},{"title":"Доля закрашенного","text":"В каждой половине закрашен один треугольник. Искомая доля равна 2/8 = 1/4."}],"keyNote":null},{"number":6,"title":"Время в приложениях","question":"Смартфон показывает общее время, которое Надя провела на прошлой неделе, пользуясь четырьмя приложениями. На этой неделе в двух приложениях она провела столько же времени, как и на прошлой, а в двух других - в два раза меньше. Какая из диаграмм соответствует её активности на этой неделе?","options":[{"image":"assets/grades-9-10/2022/task-06-answer-1.svg","description":"Длины полос сверху вниз: 2, 1, 1, ½"},{"image":"assets/grades-9-10/2022/task-06-answer-2.svg","description":"Длины полос сверху вниз: 4, 2, 1, 1"},{"image":"assets/grades-9-10/2022/task-06-answer-3.svg","description":"Длины полос сверху вниз: 2, 2, 1, 1"},{"image":"assets/grades-9-10/2022/task-06-answer-4.svg","description":"Длины полос сверху вниз: 3, 1, 1, ½"},{"image":"assets/grades-9-10/2022/task-06-answer-5.svg","description":"Длины полос сверху вниз: 2, 1, 1, 1"}],"condition":{"src":"assets/grades-9-10/2022/task-06.svg","width":138,"height":138,"alt":"Диаграмма прошлой недели. Длины полос сверху вниз: 4, 2, 2, 1"},"answer":2,"points":3,"review":[{"title":"Читаем исходные полосы","text":"Если взять отрезок сетки за единицу, длины полос сверху вниз равны 4, 2, 2 и 1."},{"title":"Сравниваем диаграммы","text":"В варианте В длины 2, 2, 1 и 1. Первая и третья полосы вдвое короче, вторая и четвёртая длины сохранили. Остальные диаграммы не дают нужного сочетания."}],"keyNote":null},{"number":7,"title":"Сколько шансов на победу","question":"В школьных выборах участвуют пять кандидатов. После подсчёта 90% бюллетеней предварительные результаты распределения голосов таковы: Аня – 14, Боря – 11, Витя – 10, Галя – 8, Дима – 2. У скольких кандидатов ещё есть шанс выиграть выборы?","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Оставшиеся бюллетени","text":"Сумма подсчитанных голосов равна 14 + 11 + 10 + 8 + 2 = 45. Это 90% голосов, всего их 50 и остались 5."},{"title":"Шансы кандидатов","text":"Если все пять голосов отдать одному кандидату, возможные итоги 19, 16, 15, 13 или 7. Первые три результата превосходят 14, последние два — нет. Победить ещё могут трое."}],"keyNote":null},{"number":8,"title":"Площади пяти квадратов","question":"На рисунке изображены пять квадратов и два прямоугольных треугольника. Площади трёх квадратов известны и записаны внутри них. Чему равна площадь квадрата со знаком вопроса?","options":[{"text":"14 м²"},{"text":"15 м²"},{"text":"16 м²"},{"text":"17 м²"},{"text":"18 м²"}],"condition":{"src":"assets/grades-9-10/2022/task-08.svg","width":262,"height":154,"alt":"У левого треугольника квадраты на катетах имеют площади 22 и 3, у правого — 8 и неизвестную площадь. Общий квадрат построен на обеих гипотенузах"},"answer":3,"points":3,"review":[{"title":"Общая гипотенуза","text":"Сторона центрального квадрата служит гипотенузой каждого прямоугольного треугольника. По теореме Пифагора площадь центрального квадрата равна 22 + 3 = 25."},{"title":"Правый треугольник","text":"Для него та же площадь равна 8 плюс искомая площадь. Она равна 25 − 8 = 17 м²."}],"keyNote":null},{"number":9,"title":"Цифры на карточках Риты","question":"Рита написала на 20 карточках число 22, а на 22 карточках число 20. Чему равна сумма всех цифр, записанных на карточках?","options":[{"text":"120"},{"text":"124"},{"text":"128"},{"text":"132"},{"text":"144"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Цифры на одной карточке","text":"У числа 22 сумма цифр 4, у числа 20 сумма цифр 2."},{"title":"Все карточки","text":"На двадцати карточках первого вида сумма 20 × 4 = 80. На двадцати двух второго — 22 × 2 = 44. Всего 124."}],"keyNote":null},{"number":10,"title":"Крыши зданий","question":"На крышах квадратных зданий, изображённых на рисунке, могут быть построены другие квадратные здания. Сторона самого большого здания равна 40 метров, второго по размеру - 20 метров, также у двух зданий сторона равна 10 метров, а у трёх - 5 метров. Крыши зданий покрасили серым цветом. Чему равна площадь покрашенной поверхности?","options":[{"text":"1600 м²"},{"text":"2100 м²"},{"text":"2150 м²"},{"text":"2275 м²"},{"text":"2500 м²"}],"condition":{"src":"assets/grades-9-10/2022/task-10.svg","width":254,"height":196,"alt":"На крыше большого квадратного здания построены квадратные здания меньшего размера. Некоторые из них стоят друг на друге. Видимые крыши серые"},"answer":0,"points":3,"review":[{"title":"Вид сверху","text":"Когда на крыше стоит здание, его верхняя крыша закрывает часть нижней той же площади. В проекции сверху серые участки в точности покрывают квадрат самого большого здания."},{"title":"Площадь крыш","text":"Сторона этого квадрата равна 40 м. Площадь окрашенной поверхности равна 40 × 40 = 1600 м²."}],"keyNote":null},{"number":11,"title":"Круги на одной прямой","question":"На рисунке изображены три большие окружности, чьи радиусы одинаковы, и четыре маленькие окружности, чьи радиусы одинаковы и равны 1 см. Центры всех окружностей и точки их касания лежат на одной прямой. Чему равна площадь закрашенной области?","options":[{"text":"π"},{"text":"2π"},{"text":"3π"},{"text":"4π"},{"text":"6π"}],"condition":{"src":"assets/grades-9-10/2022/task-11.svg","width":234,"height":123,"alt":"Три равных больших круга частично перекрываются. На общей горизонтальной оси расположены четыре касающихся маленьких круга. Некоторые области между окружностями закрашены"},"answer":1,"points":4,"review":[{"title":"Переносим области","text":"Серые участки справа совпадают по форме с двумя незакрашенными участками слева. После переноса серое займёт большой круг с двумя маленькими круглыми вырезами."},{"title":"Вычисляем площадь","text":"Диаметр малого круга равен 2 см и совпадает с радиусом большого. Искомая площадь равна π × 2² − 2π × 1² = 2π см²."}],"keyNote":null},{"number":12,"title":"Маршруты Алисы","question":"Алиса хочет попасть из X в Y. Она может перейти с одного шестиугольника на другой, только если у них есть общая сторона. При этом её путь должен включать все семь белых шестиугольников. Сколько различных маршрутов из X в Y есть у Алисы, если через каждый белый шестиугольник она может пройти лишь один раз?","options":[{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"},{"text":"6"}],"condition":{"src":"assets/grades-9-10/2022/task-12.svg","width":152,"height":189,"alt":"Кольцо из шести белых шестиугольников окружает седьмой. Серые X и Y примыкают к двум соседним верхним белым шестиугольникам"},"answer":3,"points":4,"review":[{"title":"Порядок внешних клеток","text":"Из X можно начать только в соседней белой клетке. У Y нужно закончить в соседней с ней клетке. Чтобы пройти внешнее кольцо целиком, нужно идти от первой клетки до последней по длинной дуге кольца."},{"title":"Переход через центр","text":"Центральную клетку можно вставить между любой соседней парой на этой дуге. На ней шесть клеток и пять переходов, поэтому маршрутов пять."}],"keyNote":null},{"number":13,"title":"Шесть братьев-коал","question":"Кенгуру встретил в лесу шесть братьев-коал, возрасты которых выражаются шестью последовательными целыми числами. Кенгуру спросил каждого из них, сколько лет их самому старшему брату. Какое из следующих чисел не может быть суммой шести ответов, которые получил Кенгуру?","options":[{"text":"95"},{"text":"125"},{"text":"167"},{"text":"205"},{"text":"233"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Ответы братьев","text":"Пусть старшему брату n лет. Остальные пятеро называют n, а он называет возраст следующего по старшинству брата, n − 1."},{"title":"Проверяем остаток","text":"Сумма 6n − 1 должна давать остаток 5 при делении на 6. Только 205 этому условию не удовлетворяет."}],"keyNote":null},{"number":14,"title":"Сколько лет бабушке","question":"Бабушка предложила троим внукам угадать, сколько ей лет, на что получила три ответа: 81, 78 и 75. Оказалось, что один из внуков ошибся на 1 год, другой на 2 года, а третий на 4. Сколько лет бабушке?","options":[{"text":"76"},{"text":"77"},{"text":"79"},{"text":"80"},{"text":"Нельзя определить однозначно"}],"condition":null,"answer":4,"points":4,"review":[{"title":"Два возможных возраста","text":"Если бабушке 77, ошибки при ответах 81, 78, 75 равны 4, 1, 2 годам. Если ей 79, ошибки равны 2, 1, 4 годам. Обе возможности подходят."}],"keyNote":null},{"number":15,"title":"Стороны прямоугольника","question":"Прямоугольник ABCD на рисунке состоит из 12 одинаковых прямоугольников. Чему равно отношение AD : DC?","options":[{"text":"8/9"},{"text":"5/6"},{"text":"7/8"},{"text":"2/3"},{"text":"9/8"}],"condition":{"src":"assets/grades-9-10/2022/task-15.svg","width":236,"height":165,"alt":"Верхний ряд прямоугольника ABCD состоит из трёх горизонтальных деталей. Нижняя часть выложена из горизонтальных и вертикальных деталей"},"answer":0,"points":4,"review":[{"title":"Ширина по двум разбиениям","text":"Пусть a и b — короткая и длинная стороны детали. По верхнему ряду DC = 3b. По нижней части DC = 3a + b, поэтому b = 1,5a."},{"title":"Отношение сторон","text":"По краю AD видны две длинные и одна короткая стороны. Значит, AD : DC = (2b + a)/(3b) = 4a/(4,5a) = 8/9."}],"keyNote":null},{"number":16,"title":"Забег кролика и ежа","question":"Кролик и ёж одновременно начинают бежать в противоположных направлениях на круговом треке длиной 550 метров. Кролик бежит со скоростью 10 м/с, что в десять раз быстрее скорости ежа. Когда они встретились на беговой дорожке, ёж тут же развернулся и побежал за кроликом. На сколько секунд кролик финишировал раньше, чем ёж?","options":[{"text":"45 с"},{"text":"50 с"},{"text":"55 с"},{"text":"100 с"},{"text":"505 с"}],"condition":null,"answer":0,"points":4,"review":[{"title":"Встреча на круге","text":"Скорость ежа равна 1 м/с. При беге навстречу их суммарная скорость 11 м/с. До встречи проходит 550/11 = 50 секунд."},{"title":"Возвращение к старту","text":"Ёж пробежал 50 м и после разворота пробегает их обратно, всего 100 секунд. Кролик пробегает круг за 55 секунд. Разница равна 45 секундам."}],"keyNote":null},{"number":17,"title":"Равные области квадрата","question":"В квадрате PQRS со стороной 1, точка U - середина стороны RS, а W - точка пересечения диагоналей. Точки T и V выбраны на сторонах квадрата так, что площади PQTWV, VWUS и WTRU равны. Чему равна длина отрезка SV?","options":[{"text":"1/2"},{"text":"2/3"},{"text":"3/4"},{"text":"4/5"},{"text":"5/6"}],"condition":{"src":"assets/grades-9-10/2022/task-17.svg","width":212,"height":213,"alt":"P и Q — верхняя и нижняя левые вершины, S и R — правые. Точка W в центре соединена с V на верхней стороне, T на нижней и U посередине правой стороны"},"answer":4,"points":4,"review":[{"title":"Площадь трапеции","text":"Часть VWUS имеет площадь 1/3. Это трапеция с параллельными сторонами SV и UW. Отрезок UW и высота трапеции равны 1/2."},{"title":"Длина верхней стороны","text":"По формуле площади (SV + 1/2) × (1/2)/2 = 1/3. Отсюда SV = 4/3 − 1/2 = 5/6."}],"keyNote":null},{"number":18,"title":"Деревья у тропинок","question":"В центре парка с тремя тропинками растёт дерево. Какое наименьшее количество деревьев нужно посадить, чтобы по обеим сторонам от каждой тропинки росло одинаковое количество деревьев?","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"}],"condition":{"src":"assets/grades-9-10/2022/task-18.svg","width":140,"height":140,"alt":"Три извилистые тропинки разделяют прямоугольный парк на семь областей. Одно дерево находится в центральной области"},"answer":2,"points":4,"review":[{"title":"Одного дерева мало","text":"По другую сторону от каждой тропинки от исходного дерева должно оказаться новое дерево. На схеме нет области, которая была бы по другую сторону сразу всех трёх тропинок."},{"title":"Трёх деревьев хватает","text":"Общее число деревьев должно быть чётным, поэтому добавить два тоже нельзя. Посадим по дереву в областях A, E и F. Тогда с каждой стороны каждой тропинки по два дерева.","image":"assets/grades-9-10/2022/solution-18-1.svg","imageWidth":265,"imageHeight":272}],"keyNote":null},{"number":19,"title":"Кольца на пальцах","question":"Вероника носит на руке пять колец, как показано на рисунке. Сколькими способами она может их снять, снимая по одному кольцу за раз?","options":[{"text":"16"},{"text":"20"},{"text":"24"},{"text":"30"},{"text":"45"}],"condition":{"src":"assets/grades-9-10/2022/task-19.svg","width":100,"height":156,"alt":"Три кольца на безымянном пальце и ещё по одному на двух других пальцах"},"answer":1,"points":4,"review":[{"title":"Порядок на одном пальце","text":"Три кольца безымянного пальца можно снимать только снаружи внутрь. Два других кольца можно снять в любые моменты."},{"title":"Считаем места","text":"Для первого одиночного кольца выбираем один из пяти моментов, для второго — один из четырёх оставшихся. Остальные три места заполняются однозначно. Получаем 20 способов."}],"keyNote":null},{"number":20,"title":"Треугольники разных размеров","question":"Кенгуру нарисовал 11 равносторонних треугольников. Сумма площадей трёх наименьших треугольников равна 1. Чему равна площадь наибольшего треугольника?","options":[{"text":"27"},{"text":"42"},{"text":"45"},{"text":"48"},{"text":"49"}],"condition":{"src":"assets/grades-9-10/2022/task-20.svg","width":290,"height":166,"alt":"Мозаика из одиннадцати соприкасающихся равносторонних треугольников. Самый большой выделен серым"},"answer":3,"points":4,"review":[{"title":"Длины сторон","text":"Возьмём сторону самого малого треугольника за x. Сравнивая общие края на рисунке, получаем длины 2x, 2x, 3x, 4x, 5x, 7x, 9x и 12x у остальных восьми треугольников."},{"title":"Масштаб площадей","text":"Три наименьших треугольника одинаковы и имеют площадь 1/3 каждый. Сторона большого в 12 раз длиннее, его площадь равна 12² × 1/3 = 48."}],"keyNote":null},{"number":21,"title":"Вписанные квадраты","question":"В два одинаковых равнобедренных прямоугольных треугольника вписаны квадраты P и R. Площадь квадрата P равна 45. Чему равна площадь квадрата R?","options":[{"text":"35"},{"text":"40"},{"text":"45"},{"text":"50"},{"text":"60"}],"condition":{"src":"assets/grades-9-10/2022/task-21.svg","width":324,"height":154,"alt":"Квадрат P расположен в прямом углу первого треугольника. Сторона квадрата R лежит на гипотенузе второго"},"answer":1,"points":5,"review":[{"title":"Первый треугольник","text":"Диагональ P делит квадрат на два равных треугольника. Вместе с двумя внешними частями получаем четыре одинаковых треугольника. Площадь большого треугольника равна 2 × 45 = 90."},{"title":"Второй треугольник","text":"Диагонали R вместе с высотами внешних частей разбивают большой треугольник на девять одинаковых треугольников. Четыре входят в квадрат R. Его площадь равна 4 × (90/9) = 40.","image":"assets/grades-9-10/2022/solution-21-1.svg","imageWidth":558,"imageHeight":267}],"keyNote":null},{"number":22,"title":"Очки чемпионата","question":"Восемь команд участвуют в футбольном чемпионате, где любая команда играет по одному разу с каждой из семи команд своих соперников. В каждой игре победитель получает 3 очка, а проигравший ни одного. Если игра заканчивается вничью, обе команды получают по 1 очку. В конце турнира общее число очков, заработанных всеми командами, равно 61. Чему равно наибольшее возможное число очков у выигравшей чемпионат команды?","options":[{"text":"16"},{"text":"17"},{"text":"18"},{"text":"19"},{"text":"21"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Матчи с победителем","text":"Всего сыграно 8 × 7/2 = 28 матчей. При всех ничьих было бы 56 очков. Каждый матч с победителем добавляет одно очко. Значит, таких матчей 61 − 56 = 5."},{"title":"Очки лидера","text":"Одна команда может выиграть все пять результативных матчей и сыграть два оставшихся вничью. Она наберёт 5 × 3 + 2 = 17 очков. Больше пяти побед в турнире нет."}],"keyNote":null},{"number":23,"title":"Пиратский клад","question":"Команда пиратов делит между собой клад из 200 золотых и 600 серебряных монет. Каждый пиратский офицер получил по 5 золотых и 10 серебряных монет, каждый матрос - по 3 золотых и 8 серебряных, а каждый юнга - по 1 золотой и 6 серебряных монет. Сколько пиратов делило клад?","options":[{"text":"50"},{"text":"60"},{"text":"72"},{"text":"80"},{"text":"90"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Разница у каждого пирата","text":"Офицер, матрос и юнга получили на пять серебряных монет больше, чем золотых."},{"title":"Разница всего клада","text":"Серебряных монет на 600 − 200 = 400 больше. Каждому пирату приходится по пять монет разницы, значит пиратов 400/5 = 80."}],"keyNote":null},{"number":24,"title":"Символы на гранях куба","question":"Каждая грань куба 2×2×2 разбита на 4 квадрата. На каждом квадрате нарисован один из трёх символов: круг, квадрат или крест. Эти символы различны для любых двух квадратов с общей стороной. На рисунке изображён один из вариантов расположения символов. Какая из следующих комбинаций возможна для такого куба?","options":[{"text":"6 кругов, 8 квадратов, остальные кресты"},{"text":"7 кругов, 8 квадратов, остальные кресты"},{"text":"5 кругов, 8 квадратов, остальные кресты"},{"text":"7 кругов, 7 квадратов, остальные кресты"},{"text":"Ни одна из перечисленных"}],"condition":{"src":"assets/grades-9-10/2022/task-24.svg","width":168,"height":178,"alt":"На каждой видимой грани куба 2 на 2 знаки круга, квадрата или креста распределены по четырём клеткам"},"answer":4,"points":5,"review":[{"title":"Три квадрата у вершины","text":"В каждой вершине куба сходятся три клетки, имеющие попарно общие стороны. Их символы должны быть различны, поэтому там есть круг, квадрат и крест."},{"title":"Восемь вершин","text":"Каждая клетка 2×2 на грани примыкает ровно к одной вершине. Всего по восемь символов каждого вида. Такой комбинации среди вариантов нет."}],"keyNote":null},{"number":25,"title":"Позитивисты и негативисты","question":"Жители города общаются с помощью вопросов. Все жители делятся на два типа: позитивисты и негативисты. Позитивисты всегда задают вопрос с ответом «да», а негативисты - с ответом «нет». Юра встретил на улице этого города Колю и Олю, и Оля задала Юре вопрос: «Коля и я – оба негативисты?» К какому типу жителей принадлежат Коля и Оля?","options":[{"text":"Оба позитивисты"},{"text":"Оба негативисты"},{"text":"Коля позитивист, Оля негативист"},{"text":"Коля негативист, Оля позитивист"},{"text":"Недостаточно информации, чтобы определить однозначно"}],"condition":null,"answer":2,"points":5,"review":[{"title":"Тип Оли","text":"Если бы Оля была позитивисткой, верным был бы ответ «да», то есть она оказалась бы негативисткой. Значит, Оля негативистка."},{"title":"Тип Коли","text":"Ответ на её вопрос — «нет». Оля негативистка, но оба негативистами быть не могут. Коля позитивист."}],"keyNote":null},{"number":26,"title":"Три группы гирь","question":"Продавец использует для взвешиваний 12 гирь с весами, выражающимися различными натуральными числами от 1 до 12. Гири разбиты на три группы по четыре в каждой. Общий вес первой группы равен 41 кг, а второй группы - 26 кг. Какая из гирь находится в той же группе, что и гиря весом 9 кг?","options":[{"text":"3 кг"},{"text":"5 кг"},{"text":"7 кг"},{"text":"8 кг"},{"text":"10 кг"}],"condition":null,"answer":2,"points":5,"review":[{"title":"Самая лёгкая группа","text":"Общая масса равна 78 кг, поэтому третья группа весит 78 − 41 − 26 = 11 кг. Четыре самые лёгкие гири дают 10 кг. Чтобы получить 11, нужно заменить 4 кг на 5 кг и взять 1, 2, 3, 5."},{"title":"Самая тяжёлая группа","text":"Четыре самые тяжёлые гири дают 42 кг. Для 41 кг нужно заменить 9 кг на 8 кг, получая 8, 10, 11, 12. Остаются 4, 6, 7 и 9 кг, значит с 9 кг лежит 7 кг."}],"keyNote":null},{"number":27,"title":"Треугольник между квадратами","question":"Длины диагоналей квадратов ABCD и EFGB равны 7 см и 10 см соответственно. Диагонали квадрата ABCD пересекаются в точке P. Чему равна площадь треугольника FPD?","options":[{"text":"14,5 см²"},{"text":"15 см²"},{"text":"15,75 см²"},{"text":"16,5 см²"},{"text":"17,5 см²"}],"condition":{"src":"assets/grades-9-10/2022/task-27.svg","width":170,"height":249,"alt":"Квадрат ABCD сверху, квадрат EFGB ниже. Они имеют общую точку B и перекрывающиеся стороны AB и EB. Выделен треугольник FPD"},"answer":4,"points":5,"review":[{"title":"Большой треугольник","text":"Диагонали FB и BD перпендикулярны, так как идут под углом 45° к общей горизонтальной прямой в разные стороны. Площадь FBD равна 7 × 10/2 = 35 см²."},{"title":"Половина площади","text":"P — середина BD, поэтому FP делит треугольник FBD на две равновеликие части. Площадь FPD равна 35/2 = 17,5 см²."}],"keyNote":null},{"number":28,"title":"Произведение цифр","question":"Произведение цифр положительного натурального числа N равно 20. Чему не может быть равно произведение цифр числа N+1?","options":[{"text":"24"},{"text":"25"},{"text":"30"},{"text":"35"},{"text":"40"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Какие цифры входят в N","text":"Возможны только цифры 1, 2, 4 и 5, так как каждая должна делить 20. Последняя цифра не 9, значит при прибавлении единицы меняется только она. Цифра 7 появиться не может, а без неё произведение 35 невозможно."},{"title":"Остальные произведения","text":"Числа 45, 54, 2512 и 2251 имеют произведение цифр 20. У следующих за ними чисел получаются соответственно 24, 25, 30 и 40."}],"keyNote":null},{"number":29,"title":"Касающиеся окружности","question":"На рисунке изображены окружности с центрами в точках A, B, C, D и E. Отрезками соединены центры касающихся окружностей. Известно, что AB = 16, BC = 14, CD = 17, DE = 13 и AE = 14. В какой точке находится центр окружности наибольшего радиуса?","options":[{"text":"A"},{"text":"B"},{"text":"C"},{"text":"D"},{"text":"E"}],"condition":{"src":"assets/grades-9-10/2022/task-29.svg","width":254,"height":240,"alt":"Пять окружностей касаются по циклу A, B, C, D, E. Центры соединены отрезками"},"answer":0,"points":5,"review":[{"title":"Суммы соседних радиусов","text":"Длины соединительных отрезков равны суммам пар радиусов. Их сумма 16 + 14 + 17 + 13 + 14 = 74. Каждый радиус учтён дважды, сумма пяти радиусов равна 37."},{"title":"Наибольший радиус","text":"Для A вычтем из 37 отрезки BC и DE: 37 − 14 − 13 = 10. Так же для B, C, D, E получаем 6, 8, 9 и 4. Наибольший радиус у A."}],"keyNote":null},{"number":30,"title":"Отверстия в кубе","question":"На каждой грани куба вырезано отверстие в форме половины сферы с центром в точке пересечения диагоналей этой грани. Размер отверстий одинаковый, причём, отверстия на любых двух соседних гранях касаются в одной точке. Чему равен диаметр этих отверстий, если ребро куба равно 2?","options":[{"text":"1"},{"text":"2"},{"text":"√2"},{"text":"3/2"},{"text":"√(3/2)"}],"condition":{"src":"assets/grades-9-10/2022/task-30.svg","width":166,"height":180,"alt":"Куб с круглыми отверстиями по центру трёх видимых граней"},"answer":2,"points":5,"review":[{"title":"Сечение куба","text":"Проведём через центры соседних отверстий сечение, перпендикулярное общему ребру их граней. Получим квадрат со стороной 2. Центры отверстий лежат в серединах соседних сторон квадрата."},{"title":"Расстояние между центрами","text":"Центры равноразмерных полусфер, касающихся в одной точке, находятся на расстоянии двух радиусов. Отрезок между ними — гипотенуза с катетами 1 и 1. Диаметр равен √2."}],"keyNote":null}]}];
'use strict';

(() => {
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const visual = globalThis.KenguruVisual;
  const cyrillicAnswers = 'АБВГД';

  function circleComparison(step, frame) {
    const outline = '#54877e';
    const fill = ['#347d75', '#43998c', '#60a99d', '#2e807c'];
    const ink = '#172e34';
    const radius = 43;
    const quarter = 'M0 0H43A43 43 0 0 0 0 -43Z';
    if (step === 1) {
      const opacity = .25 + .75 * visual.reveal(frame);
      return visual.svg(`<rect x="225" y="20" width="190" height="190" rx="3" fill="#f1f6ee" stroke="${outline}" stroke-width="2"/>
        <path d="M320 115H415A95 95 0 0 0 320 20Z" fill="${fill[0]}" opacity="${opacity}"/>
        <path d="M320 123V130M415 123V130M320 126H415" fill="none" stroke="${ink}" stroke-width="2"/>
        <text x="367.5" y="154" fill="${ink}" font-size="17" text-anchor="middle">радиус</text>`,
      'Радиус четверти круга равен половине стороны квадрата', '0 0 640 230', 'worked-scene');
    }
    if (step !== 2) return null;

    const far = radius;
    const offsets = [
      [[-far, far], [-far, -far], [far, -far], [far, far]],
      [[0, 0], [0, 0], [0, 0], [0, 0]],
      [[-far, 0], [-far, 0], [far, 0], [far, 0]],
      [[0, far], [-far, -far], [far, -far], [0, far]],
    ];
    const groups = offsets.map((pieces, index) => {
      const x = index % 2 === 0 ? 222 : 418;
      const y = index < 2 ? 95 : 254;
      const start = index * .38;
      const turn = index === 1 ? 0 : 180 * visual.reveal((frame - start) * 2.5);
      const remaining = 1 - visual.reveal((frame - start - 1.2) * 1.15);
      const paths = pieces.map(([dx, dy], piece) =>
        `<path d="${quarter}" fill="${fill[piece]}" stroke="#fffefa"
          stroke-width=".6" transform="translate(${x + dx * remaining} ${y + dy * remaining}) rotate(${90 * piece + turn})"/>`
      ).join('');
      return `<rect x="${x - radius}" y="${y - radius}" width="${radius * 2}" height="${radius * 2}"
        fill="#f1f6ee" stroke="${outline}" stroke-width="1.6"/>${paths}
        <text x="${x - 96}" y="${y + 6}" fill="${ink}" font-size="20" text-anchor="middle">${cyrillicAnswers[index]}</text>`;
    });
    return visual.svg(groups.join(''), 'Четыре четверти каждого рисунка складываются в целый круг',
      '102 0 432 348', 'worked-scene');
  }

  function shadeCells(step, frame) {
    if (step !== 2) return null;
    const alreadyShaded = [2, 4, 7, 9];
    const newlyShaded = [0, 1];
    const cells = Array.from({length: 12}, (_, index) => {
      const x = 90 + index % 4 * 42;
      const y = 20 + Math.floor(index / 4) * 42;
      const change = newlyShaded.indexOf(index);
      const opacity = alreadyShaded.includes(index) ? 1 : change < 0 ? 0 : visual.reveal(frame * 2 - change * .65);
      return `<rect x="${x}" y="${y}" width="42" height="42" fill="#fff"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="#202020" opacity="${opacity}"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="none" stroke="#202020" stroke-width="1.2"/>`;
    });
    return visual.svg(cells.join(''), 'В двух белых клетках верхней строки появляется чёрная заливка',
      '65 6 218 154', 'worked-scene');
  }

  const editions = [...(globalThis.KENGURU_GRADES_7_8 ?? []), ...(globalThis.KENGURU_JUNIOR_SENIOR ?? [])];
  for (const edition of editions) {
    const answerLetters = [...(edition.answerLetters ?? cyrillicAnswers)];
    const {id, year, label, grades, tasksUrl, answersUrl, solutionUrl, cards} = edition;
    const lessons = [];
    const scenes = [];

    for (const {number, title, question, questionNote, options, condition, answer, points, review, keyNote} of cards) {
      const hasReview = review.length > 0;
      const choiceImages = options.map(option => option.image);
      const choices = options.map(option => option.text ?? '');
      const answerLetter = answerLetters[answer];
      const steps = [['Условие', 'Условие задачи', '']];
      for (const [index, stage] of review.entries()) {
        const final = index === review.length - 1;
        steps.push([final ? 'Ответ' : 'Шаг ' + (index + 1), stage.title, stage.text]);
      }
      if (!hasReview) {
        steps.push(['Ответ', 'Проверка по ключу', keyNote ?? (answerLetter ? 'Правильный вариант — ' + answerLetter + '.' : 'Сверь решение с ответом в PDF.')]);
      }

      lessons.push({
        number, title, short: title, question, questionNote, points, answer, choices, choiceImages,
        choiceLayout: {condition, options}, conditionImage: condition?.src, conditionAlt: condition?.alt,
        hideIntroText: true, paperEdition: !hasReview, showCompletedStep: hasReview,
        officialValueKey: answer === null,
        steps,
      });

      const keyedAnswer = visual.answerScene({letter: answerLetter, value: choices[answer]});
      scenes.push((step, frame) => {
        if (!step) return '';
        if (!hasReview) return keyedAnswer;
        const stage = review[step - 1];
        const animation = id === '2026-7-8' && number === 1 ? circleComparison(step, frame)
          : id === '2017-2' && number === 6 ? shadeCells(step, frame) : null;
        return animation ?? (visual.workedScene(stage, frame)
          || (step === review.length ? keyedAnswer : ''));
      });
    }
    archive[id] = {id, year, label, grades, answerLetters, sources: {tasksUrl, answersUrl, solutionUrl}, lessons, scenes};
  }
})();

register((globalThis.KENGURU_ARCHIVE["2022-9-10"] ?? [].concat(globalThis.KENGURU_ARCHIVE[2022] ?? []).find(edition => edition.id === "2022-9-10")), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
